from lib import *
S = SS('k59')
F1 = [['写入 before', '明文'], ['加 --encryption-provider-config', 'apiserver 重启'], ['新建 after', 'k8s:enc:aescbc:v1:key1:…'], ['before', '仍是明文'], ['ConfigMap', '不在配置里,仍是明文']]
F2 = [['get secrets -o json', ''], ['kubectl replace -f -', 'resourceVersion 503→563'], ['before', '变成 key1 密文']]
F3 = [['配置 key1+key2', 'key1 在前'], ['key2 放最前', '要重启才生效'], ['删掉 key1(没重写)', '读不出来'], ['加回 key1', '又能读'], ['全部重写', '前缀 key2']]
PANELS = [('f', 'flow', '静态加密'), ('t', 'term', '实测输出'), ('kv', 'kv', '要点')]
steps = [
    step("先在没加密的集群里写 Secret before(etcd 里 230 字节,明文 hunter2 可直接找到)。给 kube-apiserver 静态 Pod 加 --encryption-provider-config(AES-CBC 的 key1 + identity 兜底),等了 56 秒新 apiserver 就绪。之后新建的 after 在 etcd 里是 k8s:enc:aescbc:v1:key1:… 开头的 279 字节密文,找不到明文;before 没动过,仍是明文;kubectl 读两个都正常(按前缀选解密方式)。同时创建的 ConfigMap 不在配置的 resources 里,etcd 里仍是明文。", f=fl(F1, cur=[2], mark=[3, 4], done=[0, 1]), t=tl(S(1), mark=lidx(S(1), 'k8s:enc:aescbc', 'before(没动过)', 'ConfigMap'), done=lidx(S(1), '都正常')), kv=KV([['开启后', '只有之后的写入才加密'], ['旧数据', '保持明文,直到被重写'], ['resources', '只加密配置里列出的资源']], ['旧数据'])),
    step("kubectl get secrets -o json | kubectl replace -f -:before 的 resourceVersion 从 503 变成 563(replace 是一次真实写入),etcd 里变成 k8s:enc:aescbc:v1:key1:… 开头的 279 字节密文,找不到明文。这就是让存量数据也加密的办法:全部读出再写一遍。", f=fl(F2, cur=[1], done=[0, 2]), t=tl(S(2), mark=lidx(S(2), 'resourceVersion'), done=lidx(S(2), 'replace -f -')), kv=KV([['存量数据', '必须重写才加密'], ['replace', '读出来再原样写回,服务端用新密钥加密'], ['resourceVersion', '会变,watch 的人会收到更新事件']], ['存量数据'])),
    step("轮换 key:配置里同时列 key1、key2,key1 在最前,新建的 rot1 仍用 key1。把 key2 放到最前并写回配置文件:150 秒内 apiserver 没有自动重新加载,重启 apiserver 之后新写入的 Secret 才用 key2;列表里保留 key1,所以 key1 写的 before 仍能读。错误示范——重写旧数据之前就把 key1 从配置里删掉(重启 apiserver 后生效):读 before 返回 InternalError … StorageError: corrupt object … data from the storage is not transformable,kubectl get secrets 整个列表都失败(StorageReadError,Key 是 /registry/secrets/k59/after),只有 key2 写的对象能读;把 key1 加回去(再重启)before 又能读,数据没丢;把所有 Secret 重写一遍后前缀才变成 key2,这时才能安全删 key1。", f=fl(F3, cur=[2], mark=[1], done=[0, 3, 4]), t=tl(S(3), mark=lidx(S(3), '没有自动重新加载', 'corrupt object', 'StorageReadError'), done=lidx(S(3), '数据没丢', '可以放心')), kv=KV([['顺序', '加新 key → 换主 key → 重写 → 删旧 key'], ['删早了', '旧密文读不出来,整个 LIST 也失败'], ['改配置文件', '本实验里 150 秒内没自动生效,需重启']], ['顺序'])),
]
A = mkartk('k59', 59, 'Kubernetes,Secret,静态加密,EncryptionConfiguration,etcd,密钥轮换,真实验证,动画演示',
    '在 kind 单节点集群里实测 etcd 静态加密:开启 --encryption-provider-config 后新建的 Secret 在 etcd 里变成 k8s:enc:aescbc:v1:key1: 开头的密文,旧数据仍是明文,ConfigMap 不在配置里也是明文;kubectl get | replace 重写后旧数据才加密;轮换密钥必须先加新 key、换主 key、全部重写后才能删旧 key——删早了对象读不出来,连列表都失败。',
    '开了静态加密之后,etcd 里到底变了什么?以前存的 Secret 会自动加密吗?换密钥的顺序错了会怎样?这篇在 kind 控制面节点里手动给 kube-apiserver 加 EncryptionConfiguration,直接读 etcd 的字节对照。',
    [('k8s:enc:aescbc:v1:key1:', 'etcd 里加密后的值的前缀;之后明文再也找不到'), ('503 → 563', 'kubectl replace 重写让旧 Secret 被加密时 resourceVersion 的变化'), ('corrupt object', '提前删掉旧 key 后读取旧 Secret 的错误;连 kubectl get secrets 列表也整个失败')],
    [('只有新写入的才加密', '<p>在没加密的集群里先写 Secret <code>before</code>(etcd 里 230 字节,明文 <code>hunter2</code> 直接可见)。给 kube-apiserver 静态 Pod 加上 <code>--encryption-provider-config</code>(AES-CBC 的 <code>key1</code> + <code>identity</code> 兜底),约 56 秒后新 apiserver 就绪。之后新建的 <code>after</code> 在 etcd 里是 <code>k8s:enc:aescbc:v1:key1:…</code> 开头的 279 字节密文,找不到明文;<code>before</code> 没动过,仍是明文;<code>kubectl</code> 读两个都正常——apiserver 按前缀选择解密方式。同时创建的 ConfigMap 不在配置的 <code>resources</code> 里,etcd 里仍是明文。</p>'),
     ('让旧数据加密:重写一遍', '<p><code>kubectl get secrets -o json | kubectl replace -f -</code>:<code>before</code> 的 <code>resourceVersion</code> 从 503 变成 563(这是一次真实的写入),etcd 里变成 <code>key1</code> 加密的 279 字节密文。存量数据没有别的办法自动加密,必须读出再写回,而且它会产生更新事件,watch 的人会收到。</p>'),
     ('轮换密钥的顺序', '<p>配置里先列 <code>key1</code>、<code>key2</code>(<code>key1</code> 在最前,只是让 apiserver 能解 <code>key2</code>),新建的 <code>rot1</code> 还是 <code>key1</code>。把 <code>key2</code> 放到最前再写回配置文件:150 秒内 apiserver 没有自动重新加载(本实验环境里的观察),重启 apiserver 后新写入的 Secret 才用 <code>key2</code>,<code>key1</code> 写的 <code>before</code> 因为列表里还保留 <code>key1</code> 仍能读。</p><p>错误示范——在重写旧数据之前就把 <code>key1</code> 从配置删掉(重启 apiserver 后生效):读 <code>before</code> 得到 <code>InternalError … StorageError: corrupt object … data from the storage is not transformable</code>;<code>kubectl get secrets</code> 整个列表都失败(<code>StorageReadError</code>),只有 <code>key2</code> 写的对象还能读。把 <code>key1</code> 加回去再重启,<code>before</code> 又能读,数据没丢;把所有 Secret 重写一遍后前缀变成 <code>key2</code>,这时才能安全地删掉 <code>key1</code>。</p>')],
    steps,
    [ENV_K + '。单节点 kind 集群 kx-enc(Kubernetes v1.37.0),先不开启加密;用 docker cp 把 EncryptionConfiguration 放进控制面节点的 /etc/kubernetes/enc,再改 /etc/kubernetes/manifests/kube-apiserver.yaml 加参数、卷和挂载,由 kubelet 重启 apiserver;etcd 的值用 etcdctl -w json 读出后解 base64 检查字节;key 是随机生成的 32 字节;每种情形各一次',
     '没有验证:kms v2 提供者与信封加密;secretbox / aesgcm 提供者的差异;--encryption-provider-config-automatic-reload 的默认值与生效条件(本实验环境里改文件后 150 秒内没有观察到自动生效,不代表它不能工作);加密对 apiserver 性能的影响;etcd 备份里的内容;对其他资源(configmaps、自定义资源)加密;多个 apiserver 实例之间的滚动顺序'],
    '静态加密', PANELS)
